package br.com.gestaoservicos.empresa.dto;
import br.com.gestaoservicos.empresa.model.TipoEmpresa; import jakarta.validation.constraints.*; import java.util.UUID;
public record EmpresaRequestDTO(@NotNull TipoEmpresa tipo, UUID matrizId, @NotBlank @Size(max=160) String razaoSocial, @Size(max=160) String nomeFantasia, @NotBlank @Pattern(regexp="\\d{11}|\\d{14}", message="Informe CPF ou CNPJ com apenas números.") String cnpj, @Size(max=40) String inscricaoEstadual, @Size(max=30) String telefone, @Email @Size(max=254) String email, @Size(max=12) String cep, @Size(max=180) String logradouro, @Size(max=30) String numero, @Size(max=120) String complemento, @Size(max=120) String bairro, @Size(max=120) String cidade, @Pattern(regexp="|[A-Z]{2}") String estado, @Size(max=700000) @Pattern(regexp="data:image/(png|jpeg);base64,[A-Za-z0-9+/=]+") String logoUrl) {}
